import { UploadIcon } from '@advui/icons'
import { forwardRef } from 'react'
import { type GetProps, type TamaguiElement, View, styled } from 'tamagui'
import { useFieldControl } from '../../hooks/useFieldControl'
import { Button } from '../button/Button'
import { Text } from '../typography/Text'
import { FileList } from './FileList'
import { type FileSelectionProps, useFileSelection } from './useFileSelection'

const FileUploadFrame = styled(View, {
  name: 'FileUpload',
  gap: '$2',
  alignItems: 'flex-start',
})

export interface FileUploadProps
  extends Omit<GetProps<typeof FileUploadFrame>, 'children' | 'defaultValue'>, FileSelectionProps {
  /** Text of the button. */
  buttonLabel?: string
  /** Shown while no file is picked. */
  emptyText?: string
  /** Accessible name of each remove button. */
  removeLabel?: (name: string) => string
  size?: 'sm' | 'md' | 'lg'
  disabled?: boolean
  invalid?: boolean
  'aria-describedby'?: string
  'aria-required'?: boolean
}

/**
 * A button that opens the file picker, with the picked files listed below.
 * Web uses the browser's dialog; iOS and Android use the app's picker from
 * `setFilePicker` (or `pickFiles`).
 */
export const FileUpload = forwardRef<TamaguiElement, FileUploadProps>(
  function FileUpload(uploadProps, ref) {
    const {
      value,
      defaultValue,
      onValueChange,
      multiple = false,
      accept,
      maxSize,
      maxFiles,
      onReject,
      pickFiles,
      buttonLabel = multiple ? 'Choose files' : 'Choose file',
      emptyText = multiple ? 'No files chosen' : 'No file chosen',
      removeLabel = (name: string) => `Remove ${name}`,
      size = 'md',
      disabled = false,
      invalid = false,
      id,
      'aria-label': ariaLabel,
      'aria-describedby': describedBy,
      'aria-required': required,
      ...props
    } = useFieldControl(uploadProps)
    const { files, remove, open, canPick, inputElement } = useFileSelection({
      value,
      defaultValue,
      onValueChange,
      multiple,
      accept,
      maxSize,
      maxFiles,
      onReject,
      pickFiles,
    })

    return (
      <FileUploadFrame ref={ref} {...props}>
        {inputElement}
        <Button
          id={id}
          variant="outline"
          size={size}
          icon={<UploadIcon />}
          disabled={disabled || !canPick}
          aria-label={ariaLabel}
          aria-describedby={describedBy}
          aria-invalid={invalid || undefined}
          aria-required={required}
          {...(invalid && { borderColor: '$error' })}
          onPress={open}
        >
          {buttonLabel}
        </Button>
        {files.length ? (
          <View alignSelf="stretch">
            <FileList
              files={files}
              onRemove={remove}
              removeLabel={removeLabel}
              disabled={disabled}
            />
          </View>
        ) : (
          <Text size="sm" tone="muted">
            {emptyText}
          </Text>
        )}
      </FileUploadFrame>
    )
  },
)

import { FileIcon, IconDefaults, XIcon } from '@advui/icons'
import { View, XStack } from 'tamagui'
import { IconButton } from '../icon-button/IconButton'
import { Text } from '../typography/Text'
import { type PickedFile, formatBytes } from './files'

/** The picked files, each with its size and a named remove button. */
export function FileList({
  files,
  onRemove,
  removeLabel,
  disabled,
}: {
  files: PickedFile[]
  onRemove: (index: number) => void
  removeLabel: (name: string) => string
  disabled?: boolean
}) {
  return (
    <View role="list" gap="$1.5">
      {files.map((file, index) => (
        <XStack
          key={`${file.name}-${index}`}
          role="listitem"
          alignItems="center"
          gap="$2.5"
          paddingLeft="$3"
          paddingRight="$1"
          paddingVertical="$1"
          borderWidth={1}
          borderColor="$border"
          borderRadius="$md"
          backgroundColor="$card"
        >
          <IconDefaults size={16} color="$mutedForeground">
            <FileIcon />
          </IconDefaults>
          <View flex={1} minWidth={0}>
            <Text size="sm" numberOfLines={1}>
              {file.name}
            </Text>
            {file.size != null ? (
              <Text size="xs" tone="muted">
                {formatBytes(file.size)}
              </Text>
            ) : null}
          </View>
          <IconButton
            size="sm"
            icon={<XIcon />}
            aria-label={removeLabel(file.name)}
            disabled={disabled}
            onPress={() => onRemove(index)}
          />
        </XStack>
      ))}
    </View>
  )
}

/** A picked file, the same shape on every platform. */
export interface PickedFile {
  name: string
  /** Bytes, when the picker reports it. */
  size?: number
  /** MIME type, e.g. `image/png`. */
  type?: string
  /** Native: the file's URI (upload it with `fetch` / `FormData`). */
  uri?: string
  /** Web: the browser `File`. */
  file?: File
}

export interface PickFilesOptions {
  multiple: boolean
  /** The `accept` of the component, e.g. `image/*,.pdf`. */
  accept?: string
}

/**
 * Opens the platform's file picker. Resolve with the picked files, or with an
 * empty array / null when the user cancels.
 */
export type PickFiles = (options: PickFilesOptions) => Promise<PickedFile[] | null | undefined>

export type FileRejectReason = 'type' | 'size' | 'count'

export interface FileRejection {
  file: PickedFile
  reason: FileRejectReason
}

// Set once at app start; a module value (not context) so it also reaches
// uploads inside native portals (sheets, dialogs), which drop React context.
let appPicker: PickFiles | undefined

/**
 * Registers the app's native file picker for every File Upload and File
 * Dropzone, e.g. with `expo-document-picker`. Web needs none: it uses the
 * browser's file dialog.
 */
export function setFilePicker(pickFiles: PickFiles | undefined) {
  appPicker = pickFiles
}

export function getFilePicker() {
  return appPicker
}

export function fromBrowserFiles(list: FileList | File[]): PickedFile[] {
  return Array.from(list, (file) => ({ name: file.name, size: file.size, type: file.type, file }))
}

/** Whether a file matches an `accept` string (`image/*`, `.pdf`, `application/json`). */
export function matchesAccept(file: PickedFile, accept?: string) {
  if (!accept) return true
  const name = file.name.toLowerCase()
  const type = (file.type ?? '').toLowerCase()
  return accept
    .split(',')
    .map((part) => part.trim().toLowerCase())
    .filter(Boolean)
    .some((rule) =>
      rule.startsWith('.')
        ? name.endsWith(rule)
        : rule.endsWith('/*')
          ? type.startsWith(rule.slice(0, -1))
          : type === rule,
    )
}

/** "12 KB", "3.4 MB". */
export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  const units = ['KB', 'MB', 'GB']
  let value = bytes / 1024
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`
}

import { useEffect } from 'react'
import { isWeb } from 'tamagui'
import { useControllableState } from '../../hooks/useControllableState'
import {
  type FileRejection,
  type PickFiles,
  type PickedFile,
  getFilePicker,
  matchesAccept,
} from './files'
import { useBrowserFilePicker } from './useBrowserFilePicker'

export interface FileSelectionProps {
  value?: PickedFile[]
  defaultValue?: PickedFile[]
  onValueChange?: (files: PickedFile[]) => void
  /** Allow several files; otherwise a new pick replaces the file. */
  multiple?: boolean
  /** Allowed types, as in `<input accept>`: `image/*,.pdf`. Also checked on drop and on native. */
  accept?: string
  /** Largest allowed file in bytes. */
  maxSize?: number
  /** Most files kept when `multiple`. */
  maxFiles?: number
  /** Called with the files that were refused and why. */
  onReject?: (rejections: FileRejection[]) => void
  /** This component's picker. Defaults to the browser dialog on web and `setFilePicker` on native. */
  pickFiles?: PickFiles
}

const none: PickedFile[] = []
let warned = false

/** Picked files, validation and the platform picker, shared by File Upload and File Dropzone. */
export function useFileSelection({
  value,
  defaultValue = none,
  onValueChange,
  multiple = false,
  accept,
  maxSize,
  maxFiles,
  onReject,
  pickFiles,
}: FileSelectionProps) {
  const [files, setFiles] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })

  const add = (incoming: PickedFile[]) => {
    const rejections: FileRejection[] = []
    const accepted: PickedFile[] = []
    for (const file of incoming) {
      if (!matchesAccept(file, accept)) rejections.push({ file, reason: 'type' })
      else if (maxSize != null && file.size != null && file.size > maxSize) {
        rejections.push({ file, reason: 'size' })
      } else accepted.push(file)
    }
    const limit = multiple ? (maxFiles ?? Infinity) : 1
    const combined = multiple ? [...files, ...accepted] : accepted
    for (const file of combined.slice(limit)) rejections.push({ file, reason: 'count' })
    if (accepted.length) setFiles(combined.slice(0, limit))
    if (rejections.length) onReject?.(rejections)
  }

  const browser = useBrowserFilePicker({ accept, multiple, onFiles: add })
  const picker = pickFiles ?? (isWeb ? undefined : getFilePicker())
  const canPick = Boolean(picker || browser.open)
  // A missing native picker is a setup mistake; say so once instead of silently disabling.
  useEffect(() => {
    if (canPick || warned) return
    warned = true
    console.warn(
      'File Upload: no file picker on this platform. Call setFilePicker() at app start ' +
        '(e.g. with expo-document-picker) or pass pickFiles.',
    )
  }, [canPick])

  const open = async () => {
    if (picker) {
      const picked = await picker({ multiple, accept })
      if (picked?.length) add(picked)
    } else browser.open?.()
  }

  const remove = (index: number) => setFiles(files.filter((_, i) => i !== index))

  return { files, add, remove, open, canPick, inputElement: browser.element }
}

import { useRef } from 'react'
import { type PickedFile, fromBrowserFiles } from './files'

/**
 * Web: a hidden `<input type="file">` that opens the browser's file dialog.
 * Render `element` anywhere in the component.
 */
export function useBrowserFilePicker({
  accept,
  multiple,
  onFiles,
}: {
  accept?: string
  multiple: boolean
  onFiles: (files: PickedFile[]) => void
}) {
  const ref = useRef<HTMLInputElement>(null)
  const element = (
    <input
      ref={ref}
      type="file"
      hidden
      aria-hidden
      tabIndex={-1}
      accept={accept}
      multiple={multiple}
      onChange={(event) => {
        const { files } = event.currentTarget
        if (files?.length) onFiles(fromBrowserFiles(files))
        // Picking the same file again must fire another change.
        event.currentTarget.value = ''
      }}
    />
  )
  return { element, open: () => ref.current?.click() }
}

import type { PickedFile } from './files'

/** Native has no browser dialog; the app's picker (`setFilePicker`) is used instead. */
export function useBrowserFilePicker(_options: {
  accept?: string
  multiple: boolean
  onFiles: (files: PickedFile[]) => void
}): { element: null; open: undefined } {
  return { element: null, open: undefined }
}

